def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # The color-4 object is the stamp. For each other same-color component,
    # place the stamp in the orientation/translation that contains all seed cells.
    seen=set(); stamp=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==4: stamp.append((r,c))
    sr0=min(r for r,c in stamp); sc0=min(c for r,c in stamp)
    base={(r-sr0,c-sc0) for r,c in stamp}
    def variants(s):
      for refl in (False,True):
        for rot in range(4):
          pts=[]
          for r,c in s:
            if refl: c=-c
            for _ in range(rot): r,c=c,-r
            pts.append((r,c))
          mr=min(r for r,c in pts); mc=min(c for r,c in pts)
          yield {(r-mr,c-mc) for r,c in pts}
    forms=list(variants(base))
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v in (1,4) or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
              seen.add((yy,xx)); q.append((yy,xx))
        src={(y-min(y for y,x in comp),x-min(x for y,x in comp)) for y,x in comp}
        cand=[]
        for form in forms:
          if not src.issubset(form): continue
          dh=max(y for y,x in form)+1; dw=max(x for y,x in form)+1
          for oy in range(h-dh+1):
            for ox in range(w-dw+1):
              if all(grid[y+oy][x+ox] in (1,v) for y,x in form):
                # prefer overlaying source exactly; then nearest bbox center
                exact=sum((y+oy,x+ox) in comp for y,x in form)
                dist=abs(oy-min(y for y,x in comp))+abs(ox-min(x for y,x in comp))
                cand.append((-exact,dist,oy,ox,form))
        if cand:
          _,_,oy,ox,form=min(cand)
          for y,x in form: out[oy+y][ox+x]=v
    return out
