def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Reference motif, normalized to its upper-left corner.
    ref=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==4]
    r0=min(r for r,c in ref); c0=min(c for r,c in ref)
    base={(r-r0,c-c0) for r,c in ref}
    forms=[]
    for flip in (False,True):
      for k in range(4):
        pts=[]
        for r,c in base:
          if flip: c=-c
          for _ in range(k): r,c=c,-r
          pts.append((r,c))
        mr=min(r for r,c in pts); mc=min(c for r,c in pts)
        forms.append({(r-mr,c-mc) for r,c in pts})
    seen=set()
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v in (1,4) or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              yy,xx=y+dy,x+dx
              if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
                seen.add((yy,xx)); q.append((yy,xx))
        candidates=[]
        for form in forms:
          for oy in range(h):
            for ox in range(w):
              if all(0<=oy+a<h and 0<=ox+b<w for a,b in form) and all((y,x) in {(oy+a,ox+b) for a,b in form} for y,x in comp):
                extra=sum(grid[oy+a][ox+b] not in (1,v) for a,b in form)
                # prefer least overlap with other motifs, then closest upper-left to source
                candidates.append((extra, abs(oy-min(y for y,x in comp))+abs(ox-min(x for y,x in comp)),oy,ox,form))
        if candidates:
          _,_,oy,ox,form=min(candidates)
          for a,b in form: out[oy+a][ox+b]=v
    return out
